ROOT.scriptdef:
set nocount on;
	insert into cdn.OpeZakazy select [OpZ_OpeTyp], [OpZ_OpeFirma], [OpZ_OpeNumer], [OpZ_OpeLp], 30814, [OpZ_MaskaFormy], [OpZ_MaskaFormyAtr], [OpZ_MaskaFormyExp] from cdn.OpeZakazy where opz_procid = 30537
set nocount off;

set nocount on;
	insert into cdn.StaZakazy select [StZ_StaTyp], [StZ_StaFirma], [StZ_StaNumer], [StZ_StaLp], 30814, [StZ_MaskaFormy], [StZ_MaskaFormyAtr], [StZ_MaskaFormyExp] from cdn.StaZakazy where StZ_ProcID = 30537
set nocount off;
